package com.mahesh.empleave.audit;import com.mahesh.empleave.user.*;import jakarta.persistence.*;import lombok.*;import java.time.*;@Entity @Getter @NoArgsConstructor(access=AccessLevel.PROTECTED) public class AuditLog{@Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id;@ManyToOne private AppUser actor;@Column(nullable=false) private String action;@Column(nullable=false) private String entityType;private Long entityId;@Column(nullable=false) private LocalDateTime createdAt=LocalDateTime.now();public AuditLog(AppUser a,String action,String type,Long id){actor=a;this.action=action;entityType=type;entityId=id;}}
